import java.util.*;
/** B-tree of minimum degree 2 for live split and median promotion tracing. */
class TeachingBTree { static final int T=2; static class N{ArrayList<Integer> keys=new ArrayList<Integer>();ArrayList<N> child=new ArrayList<N>();boolean leaf=true;} N root=new N(); boolean contains(int k){return search(root,k);} boolean search(N x,int k){int i=0;while(i<x.keys.size()&&k>x.keys.get(i))i++;if(i<x.keys.size()&&k==x.keys.get(i))return true;return !x.leaf&&search(x.child.get(i),k);} void insert(int k){if(root.keys.size()==2*T-1){N s=new N();s.leaf=false;s.child.add(root);split(s,0);root=s;}nonFull(root,k);} void split(N p,int i){N y=p.child.get(i),z=new N();z.leaf=y.leaf;int mid=y.keys.get(T-1);z.keys.add(y.keys.remove(T));y.keys.remove(T-1);if(!y.leaf){z.child.add(y.child.remove(T));z.child.add(y.child.remove(T));}p.keys.add(i,mid);p.child.add(i+1,z);System.out.println("split promoted median "+mid);} void nonFull(N x,int k){int i=x.keys.size()-1;if(x.leaf){x.keys.add(0);while(i>=0&&k<x.keys.get(i)){x.keys.set(i+1,x.keys.get(i));i--;}x.keys.set(i+1,k);}else{while(i>=0&&k<x.keys.get(i))i--;i++;if(x.child.get(i).keys.size()==2*T-1){split(x,i);if(k>x.keys.get(i))i++;}nonFull(x.child.get(i),k);}} }
